WITH base AS (SELECT * FROM web_events WHERE event_type != 'click' AND page IN ('/search', '/checkout', '/product')), agg AS (SELECT CASE WHEN page IN ('/cart', '/product') THEN 'priority' ELSE 'other' END AS page_group, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list FROM base GROUP BY CASE WHEN page IN ('/cart', '/product') THEN 'priority' ELSE 'other' END) SELECT page_group, event_type_list FROM agg ORDER BY page_group
